  localparam int O_u_s4_ld_data_o = (S2_NQ) + (S2_NQ*64) + (S2_NQ*S2_DW) + (S2_NQ*NUM_THREADS*S2_RMW) + (S2_NCOL) + (S2_NCOL) + (N_ALU*64) + (N_ALU*3) + (128) + (64) + (1) + (1) + (1);
  localparam int O_u_s4_probe_tags_o = (S2_NQ) + (S2_NQ*64) + (S2_NQ*S2_DW) + (S2_NQ*NUM_THREADS*S2_RMW) + (S2_NCOL) + (S2_NCOL) + (N_ALU*64) + (N_ALU*3) + (128) + (64) + (1) + (1) + (1) + (64);
  localparam int O_u_s5_out_valid_o = (S2_NQ) + (S2_NQ*64) + (S2_NQ*S2_DW) + (S2_NQ*NUM_THREADS*S2_RMW) + (S2_NCOL) + (S2_NCOL) + (N_ALU*64) + (N_ALU*3) + (128) + (64) + (1) + (1) + (1) + (64) + (L1_WAYS*(S4_PPN_W+2));
  localparam int O_u_s5_out_insn_o = (S2_NQ) + (S2_NQ*64) + (S2_NQ*S2_DW) + (S2_NQ*NUM_THREADS*S2_RMW) + (S2_NCOL) + (S2_NCOL) + (N_ALU*64) + (N_ALU*3) + (128) + (64) + (1) + (1) + (1) + (64) + (L1_WAYS*(S4_PPN_W+2)) + (DECODE_WIDTH);
  localparam int O_u_s5_fetch_pc_o = (S2_NQ) + (S2_NQ*64) + (S2_NQ*S2_DW) + (S2_NQ*NUM_THREADS*S2_RMW) + (S2_NCOL) + (S2_NCOL) + (N_ALU*64) + (N_ALU*3) + (128) + (64) + (1) + (1) + (1) + (64) + (L1_WAYS*(S4_PPN_W+2)) + (DECODE_WIDTH) + (DECODE_WIDTH*S5_IB_W);
  localparam int O_u_s5_if2_hit_o = (S2_NQ) + (S2_NQ*64) + (S2_NQ*S2_DW) + (S2_NQ*NUM_THREADS*S2_RMW) + (S2_NCOL) + (S2_NCOL) + (N_ALU*64) + (N_ALU*3) + (128) + (64) + (1) + (1) + (1) + (64) + (L1_WAYS*(S4_PPN_W+2)) + (DECODE_WIDTH) + (DECODE_WIDTH*S5_IB_W) + (38);
  localparam int SPK_IN  = (1) + (S2_DW) + (S2_DW*S2_QW) + (S2_DW*TID_BITS) + (S2_DW*S2_NCOL) + (S2_DW*S2_NCOL) + (S2_DW*S2_NCOL) + (S2_DW*S2_ROBW) + (S2_DW*64) + (S2_DW*S2_RA) + (S2_NCOL) + (S2_NCOL) + (S2_NCOL) + (S2_NCOL) + (1) + (1) + (TID_BITS) + (1) + (S2_ROBW) + (1) + (S3_NLOG*S3_BW) + (S3_NLOG*S3_IW) + (1) + (N_ALU) + (N_ALU*S3_CTL_W) + (N_ALU*S3_IW) + (N_ALU*64) + (N_ALU*2*S3_SW) + (2*S3_SW) + (1) + (S3_IW) + (64) + (1) + (S3_IW) + (64) + (1) + (1) + (2) + (256) + (12) + (2) + (1) + (TID_BITS) + (16) + (8) + (S4_WAY_W) + (9) + (64) + (1) + (S4_WAY_W) + (S4_SET_W) + (S4_PPN_W+2) + (S4_SET_W) + (1) + (S4_EW) + (27) + (2) + (1) + (S4_PPN_W) + (1) + (1) + (1) + (38) + (TID_BITS) + (1) + (TID_BITS) + (1) + (1) + (35) + (TID_BITS) + (38) + (S5_SW) + (1) + (S4_WAY_W) + (S5_ROWW) + (8*FETCH_BYTES) + (S4_PPN_W+1) + (1) + (4) + (27) + (S4_PPN_W) + (16) + (idx_w(DECODE_WIDTH+1));
  localparam int SPK_OUT = (S2_NQ) + (S2_NQ*64) + (S2_NQ*S2_DW) + (S2_NQ*NUM_THREADS*S2_RMW) + (S2_NCOL) + (S2_NCOL) + (N_ALU*64) + (N_ALU*3) + (128) + (64) + (1) + (1) + (1) + (64) + (L1_WAYS*(S4_PPN_W+2)) + (DECODE_WIDTH) + (DECODE_WIDTH*S5_IB_W) + (38) + (1);
  localparam int FOUT_W = ((SPK_IN + BUS_W + 15) / 16) * 16;
  localparam int FIN_W  = SPK_OUT + BUS_W;

  logic [FOUT_W-1:0] fout;   // filler registers: spike inputs, then the bus to the L2
  logic [FIN_W-1:0]  fin;    // spike outputs, then the bus from the L2

  tg_s6_fill #(.TILES(TILES), .NRAM(NRAM), .NBRAM(NBRAM), .NDSP(NDSP), .SEED(SEED),
               .IN_W(FIN_W), .OUT_W(FOUT_W)) u_fill (.clk, .in(fin), .out(fout));
  assign l2_out = fout[SPK_IN +: BUS_W];
  assign fin[SPK_OUT +: BUS_W] = l2_in;
  if (FOUT_W > SPK_IN + BUS_W) begin : g_pad
    logic unused;
    assign unused = ^fout[FOUT_W-1:SPK_IN + BUS_W];   // padding to whole tiles
  end

  tg_s2_sched_top #(.STALE(0), .WAKE_ENC(1), .DUP_SEL(1'b1), .EARLY_W(24), .MX(S2_MX != 0)) u_s2 (
    .clk,
    .rst_i(fout[I_u_s2_rst_i +: 1]),
    .disp_valid_i(fout[I_u_s2_disp_valid_i +: S2_DW]),
    .disp_queue_i(fout[I_u_s2_disp_queue_i +: S2_DW*S2_QW]),
    .disp_tid_i(fout[I_u_s2_disp_tid_i +: S2_DW*TID_BITS]),
    .disp_dep_i(fout[I_u_s2_disp_dep_i +: S2_DW*S2_NCOL]),
    .disp_dep_ph_i(fout[I_u_s2_disp_dep_ph_i +: S2_DW*S2_NCOL]),
    .disp_wake_oh_i(fout[I_u_s2_disp_wake_oh_i +: S2_DW*S2_NCOL]),
    .disp_rob_i(fout[I_u_s2_disp_rob_i +: S2_DW*S2_ROBW]),
    .disp_payload_i(fout[I_u_s2_disp_payload_i +: S2_DW*64]),
    .disp_mdep_i(fout[I_u_s2_disp_mdep_i +: S2_DW*S2_RA]),
    .llt_done_i(fout[I_u_s2_llt_done_i +: S2_NCOL]),
    .alloc_i(fout[I_u_s2_alloc_i +: S2_NCOL]),
    .cancel_ids_i(fout[I_u_s2_cancel_ids_i +: S2_NCOL]),
    .col_clr_i(fout[I_u_s2_col_clr_i +: S2_NCOL]),
    .cancel_i(fout[I_u_s2_cancel_i +: 1]),
    .flush_valid_i(fout[I_u_s2_flush_valid_i +: 1]),
    .flush_tid_i(fout[I_u_s2_flush_tid_i +: TID_BITS]),
    .flush_all_i(fout[I_u_s2_flush_all_i +: 1]),
    .flush_rob_i(fout[I_u_s2_flush_rob_i +: S2_ROBW]),
    .iss_valid_o(fin[O_u_s2_iss_valid_o +: S2_NQ]),
    .iss_payload_o(fin[O_u_s2_iss_payload_o +: S2_NQ*64]),
    .bank_free_o(fin[O_u_s2_bank_free_o +: S2_NQ*S2_DW]),
    .room_o(fin[O_u_s2_room_o +: S2_NQ*NUM_THREADS*S2_RMW]),
    .busy_o(fin[O_u_s2_busy_o +: S2_NCOL]),
    .w_o(fin[O_u_s2_w_o +: S2_NCOL])
  );

  tg_s3_top #(.BYPASS(0), .RF3(0), .SEL_OH(0)) u_s3 (
    .clk,
    .rst_i(fout[I_u_s3_rst_i +: 1]),
    .rbank_i(fout[I_u_s3_rbank_i +: S3_NLOG*S3_BW]),
    .ridx_i(fout[I_u_s3_ridx_i +: S3_NLOG*S3_IW]),
    .a2_share_i(fout[I_u_s3_a2_share_i +: 1]),
    .alu_valid_i(fout[I_u_s3_alu_valid_i +: N_ALU]),
    .alu_ctl_i(fout[I_u_s3_alu_ctl_i +: N_ALU*S3_CTL_W]),
    .alu_dest_i(fout[I_u_s3_alu_dest_i +: N_ALU*S3_IW]),
    .alu_imm_i(fout[I_u_s3_alu_imm_i +: N_ALU*64]),
    .alu_sel_i(fout[I_u_s3_alu_sel_i +: N_ALU*2*S3_SW]),
    .base_sel_i(fout[I_u_s3_base_sel_i +: 2*S3_SW]),
    .ld_valid_i(fout[I_u_s3_ld_valid_i +: 1]),
    .ld_dest_i(fout[I_u_s3_ld_dest_i +: S3_IW]),
    .ld_data_i(fout[I_u_s3_ld_data_i +: 64]),
    .oth_valid_i(fout[I_u_s3_oth_valid_i +: 1]),
    .oth_dest_i(fout[I_u_s3_oth_dest_i +: S3_IW]),
    .oth_data_i(fout[I_u_s3_oth_data_i +: 64]),
    .alu_res_o(fin[O_u_s3_alu_res_o +: N_ALU*64]),
    .alu_flags_o(fin[O_u_s3_alu_flags_o +: N_ALU*3]),
    .base_o(fin[O_u_s3_base_o +: 128]),
    .sd_o(fin[O_u_s3_sd_o +: 64])
  );

  tg_s4_top #(.ALIGN_M1(1)) u_s4 (
    .clk,
    .rst_i(fout[I_u_s4_rst_i +: 1]),
    .ld_valid_i(fout[I_u_s4_ld_valid_i +: 1]),
    .base_sel_i(fout[I_u_s4_base_sel_i +: 2]),
    .base_src_i(fout[I_u_s4_base_src_i +: 256]),
    .offset_i(fout[I_u_s4_offset_i +: 12]),
    .size_i(fout[I_u_s4_size_i +: 2]),
    .unsigned_i(fout[I_u_s4_unsigned_i +: 1]),
    .tid_i(fout[I_u_s4_tid_i +: TID_BITS]),
    .asid_i(fout[I_u_s4_asid_i +: 16]),
    .dwe_i(fout[I_u_s4_dwe_i +: 8]),
    .dway_i(fout[I_u_s4_dway_i +: S4_WAY_W]),
    .daddr_i(fout[I_u_s4_daddr_i +: 9]),
    .ddata_i(fout[I_u_s4_ddata_i +: 64]),
    .twe_i(fout[I_u_s4_twe_i +: 1]),
    .tway_i(fout[I_u_s4_tway_i +: S4_WAY_W]),
    .tset_i(fout[I_u_s4_tset_i +: S4_SET_W]),
    .ttag_i(fout[I_u_s4_ttag_i +: S4_PPN_W+2]),
    .probe_set_i(fout[I_u_s4_probe_set_i +: S4_SET_W]),
    .tf_valid_i(fout[I_u_s4_tf_valid_i +: 1]),
    .tf_idx_i(fout[I_u_s4_tf_idx_i +: S4_EW]),
    .tf_vpn_i(fout[I_u_s4_tf_vpn_i +: 27]),
    .tf_lvl_i(fout[I_u_s4_tf_lvl_i +: 2]),
