    .tf_ppn_i(fout[I_u_s4_tf_ppn_i +: S4_PPN_W]),
    .tfl_valid_i(fout[I_u_s4_tfl_valid_i +: 1]),
    .ld_valid_o(fin[O_u_s4_ld_valid_o +: 1]),
    .ld_hit_o(fin[O_u_s4_ld_hit_o +: 1]),
    .ld_cancel_o(fin[O_u_s4_ld_cancel_o +: 1]),
    .ld_data_o(fin[O_u_s4_ld_data_o +: 64]),
    .probe_tags_o(fin[O_u_s4_probe_tags_o +: L1_WAYS*(S4_PPN_W+2)])
  );

  tg_s5_top #(.FA(0), .WR(4)) u_s5 (
    .clk,
    .rst_i(fout[I_u_s5_rst_i +: 1]),
    .redirect_i(fout[I_u_s5_redirect_i +: 1]),
