    .upd_valid_i(fout[I_u_s5_upd_valid_i +: 1]),
    .upd_way_i(fout[I_u_s5_upd_way_i +: 1]),
    .upd_pc_i(fout[I_u_s5_upd_pc_i +: 35]),
    .upd_tid_i(fout[I_u_s5_upd_tid_i +: TID_BITS]),
    .upd_target_i(fout[I_u_s5_upd_target_i +: 38]),
    .upd_slot_i(fout[I_u_s5_upd_slot_i +: S5_SW]),
    .rf_valid_i(fout[I_u_s5_rf_valid_i +: 1]),
    .rf_way_i(fout[I_u_s5_rf_way_i +: S4_WAY_W]),
    .rf_row_i(fout[I_u_s5_rf_row_i +: S5_ROWW]),
    .rf_data_i(fout[I_u_s5_rf_data_i +: 8*FETCH_BYTES]),
    .rf_tag_i(fout[I_u_s5_rf_tag_i +: S4_PPN_W+1]),
    .tf_valid_i(fout[I_u_s5_tf_valid_i +: 1]),
    .tf_idx_i(fout[I_u_s5_tf_idx_i +: 4]),
    .tf_vpn_i(fout[I_u_s5_tf_vpn_i +: 27]),
    .tf_ppn_i(fout[I_u_s5_tf_ppn_i +: S4_PPN_W]),
    .asid_i(fout[I_u_s5_asid_i +: 16]),
    .take_i(fout[I_u_s5_take_i +: idx_w(DECODE_WIDTH+1)]),
    .out_valid_o(fin[O_u_s5_out_valid_o +: DECODE_WIDTH]),
    .out_insn_o(fin[O_u_s5_out_insn_o +: DECODE_WIDTH*S5_IB_W]),
    .fetch_pc_o(fin[O_u_s5_fetch_pc_o +: 38]),
    .if2_hit_o(fin[O_u_s5_if2_hit_o +: 1])
  );

  if (TILES * 16 < FOUT_W) begin : g_small
    $error("tg_s6_core: TILES too small to drive every spike input from its own register");
  end
endmodule
